from collections import deque


class PracticeQueue:
    def __init__(self):
        self._waiting = deque()

    def add(self, name):
        self._waiting.append(name)

    def next(self):
        return self._waiting.popleft() if self._waiting else None

    def waiting(self):
        return list(self._waiting)
